},{\"name\":\"Consultancy & services template\",\"does\":\"Proposal-to-delivery: CRM, projects, billing, and client-facing hub for management consultancies and professional service firms.\",\"url\":\"\",\"scope\":\"client\"},{\"name\":\"Electronics retail template\",\"does\":\"Virgin-style mega navigation, spec-heavy homepage, and SKU pagination for IT and consumer electronics. RMA and warranty hooks…\",\"url\":\"\",\"scope\":\"client\"},{\"name\":\"Fashion & beauty template\",\"does\":\"Lookbook collections, variant catalogue, and campaign-ready Namshi-style storefront. Order fulfilment and returns modules…\",\"url\":\"\",\"scope\":\"client\"},{\"name\":\"Jewellery & luxury template\",\"does\":\"Kiyasha-style gold and diamond aesthetic, gallery product cards, certificate metadata, and premium enquiry flows for fine…\",\"url\":\"\",\"scope\":\"client\"},{\"name\":\"Medical supplies template\",\"does\":\"Regulated catalogue, institutional login, batch and expiry fields, and audit-friendly delivery documentation for clinic…\",\"url\":\"\",\"scope\":\"client\"},{\"name\":\"Rental operations template\",\"does\":\"Rental SKU with daily/monthly periods, deposits, contracts, and monthly billing hooks for fleet, equipment, and commercial…\",\"url\":\"\",\"scope\":\"client\"},{\"name\":\"Tax & advisory template\",\"does\":\"Client portal, VAT workflows, document control, and advisory CRM on one hosted domain — Prime Invest-style layout for tax…\",\"url\":\"\",\"scope\":\"client\"}]}";

    internal const string CapabilityGuidesJson = "{\"super-cp-console\":{\"intro\":\"Run every tenant from one hosted console at ecomae.com/cp — same ECOM AE control panel shell with platform packs. Onboard clients, push templates, and monitor health without exposing operator tools on client domains.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Sign in at Super CP\",\"body\":\"Platform operators open the hosted console — same control panel shell as client sites with tenant orchestration packs in the sidebar.\"},{\"title\":\"Tenant registry overview\",\"body\":\"See every client: trade name, hostname, industry, database, and status from draft through live on one screen.\"},{\"title\":\"Deploy industry packs\",\"body\":\"Pick vertical, visual style, and enabled module packs — push templates to registered client targets without rebuilding per tenant.\"},{\"title\":\"Monitor health probes\",\"body\":\"HTTP checks confirm storefront and CP endpoints respond before flipping a tenant to Live status.\"}]},\"tenant-hub\":{\"intro\":\"Central registry of all clients: trade name, hostname, industry, database, and status from draft through live. One screen to see who is pending DNS, who is live, and who needs attention.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Open tenant hub\",\"body\":\"Super CP → Tenants lists all registered clients with trade name, hostname, industry code, and MySQL database name.\"},{\"title\":\"Filter by status\",\"body\":\"Quickly see who is draft, DNS pending, or live — pending DNS and failed probes surface for operator attention.\"},{\"title\":\"Drill into tenant record\",\"body\":\"Open a tenant to edit portal settings, industry template, module packs, and deploy audit history.\"}]},\"tenant-onboarding\":{\"intro\":\"Single intro form captures brand, domain, industry, admin email, and tenant MySQL details — seeds portal settings and industry template on save. Most operators go from form to working stack within 24 hours once DNS is...\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Complete intro form\",\"body\":\"Capture brand, domain, industry, admin e-mail, and tenant database credentials — portal settings and industry template apply on save.\"},{\"title\":\"Apply industry template\",\"body\":\"Nine verticals pre-load CP module packs, storefront package, and visual style — auto parts, tax, fashion, electronics, medical, jewellery, and more.\"},{\"title\":\"Hand off DNS checklist\",\"body\":\"Client adds registrar A records; operator attaches domain alias and issues SSL when probes pass.\"},{\"title\":\"Go live within 24 hours\",\"body\":\"Most operators reach a working storefront and CP stack within one business day once DNS is pointed.\"}]},\"dns-launch-checklist\":{\"intro\":\"Step-by-step GoDaddy-friendly A-record guide, domain alias on the platform stack, SSL issuance, and status flip to Live when probes pass. Clients keep their registrar — no separate hosting package.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Registrar A records\",\"body\":\"GoDaddy-friendly checklist: client adds @ and www A records pointing to the ECOM AE platform IP — no separate hosting package.\"},{\"title\":\"Domain alias on stack\",\"body\":\"Attach hostname as nginx alias on the live platform vhost — same codebase routes to the isolated tenant database by hostname.\"},{\"title\":\"SSL issuance\",\"body\":\"Let's Encrypt certificates issue on the platform stack — tenants get HTTPS on www.client.com without managing certificates.\"},{\"title\":\"Status flip to Live\",\"body\":\"When HTTP probes pass on storefront and /cp/, set tenant status to Live and hand off credentials to the client.\"}]},\"industry-settings-deploy\":{\"intro\":\"Pick vertical, visual style, enabled module packs, and sidebar visibility — then push to a client site when ready. Deploy portal packages to registered targets from Super CP without rebuilding per tenant.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Pick vertical & visual style\",\"body\":\"Super CP → Industry settings selects vertical, storefront theme, and CP chrome — fashion Namshi-style, Virgin electronics, eParts automotive, and more.\"},{\"title\":\"Enable module packs\",\"body\":\"Toggle commerce, ERP, auto parts, logistics, procurement, and e-invoice packs per rental tier.\"},{\"title\":\"Push to client site\",\"body\":\"Deploy portal packages to registered targets — sidebar groups and enabled modules update without rebuilding the tenant codebase.\"}]},\"tenant-health-probes\":{\"intro\":\"HTTP checks on live tenants confirm storefront and CP endpoints respond before handoff. Track draft → DNS pending → live with confidence that the client site is reachable.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Configure probe endpoints\",\"body\":\"Health checks hit storefront home, CP login, and optional /erp routes for each live tenant hostname.\"},{\"title\":\"Review probe results\",\"body\":\"Failed probes highlight tenants needing DNS, SSL, or database attention before customer handoff.\"},{\"title\":\"Go-live gate\",\"body\":\"Operators flip status to Live only when all configured probes return HTTP 200.\"}]},\"business-continuity-failover\":{\"intro\":\"Cloud-first operations with a professional backup path when the primary stack hiccups. Shoppers see guided splash screens instead of generic errors while traffic can route to your backup origin.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Cloud-first operations\",\"body\":\"Tenants run on ECOM AE infrastructure day to day — storefront, /cp/, and /erp on the primary cloud stack.\"},{\"title\":\"Guided splash screens\",\"body\":\"If the primary stack is unreachable, shoppers see professional step-by-step splash copy instead of generic error pages.\"},{\"title\":\"Operator failover modes\",\"body\":\"Platform operators manage connecting to backup, backup online, and restoring cloud from Super CP failover guide.\"}]},\"multi-tenant-routing\":{\"intro\":\"One nginx stack serves many client domains — hostname selects isolated MySQL tenant database and branding. Model C hosting saves disk, ops time, and per-client hosting bills.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Single nginx stack\",\"body\":\"One platform nginx vhost serves many client domains — hostname selects tenant context at request time.\"},{\"title\":\"Isolated MySQL per tenant\",\"body\":\"Each client domain maps to its own database — catalogue, orders, and ERP data never cross tenants.\"},{\"title\":\"Model C hosting savings\",\"body\":\"Shared codebase and ops reduce disk, deployment time, and per-client hosting bills versus separate VPS per shop.\"}]},\"modular-erp-access\":{\"intro\":\"Turn on only the ERP areas each company needs — from a full suite down to Custom & Shipping or People-only deployments. Shared ERP companies on www.ecomae.com use the same login URL with per-company module packs.\",\"guide_area\":\"overview\",\"image\":\"guide-erp-only\",\"steps\":[{\"title\":\"Pick modules at onboard\",\"body\":\"Tenant hub → Onboard client — tick ERP only + Hosted on ecomae.com (shared). Use ERP module presets or tick individual areas. No client domain required.\"},{\"title\":\"Adjust in Industry settings\",\"body\":\"Super CP → Industry settings → ERP modules grid. Select a tenant by site key and Save to push erp_modules_json to that company database.\"},{\"title\":\"Shell hides disabled areas\",\"body\":\"Staff only see enabled sidebar groups at www.ecomae.com/cp/shop/finance/erp?epc_erp_shell=1 after company login.\"},{\"title\":\"Separate DB per company\",\"body\":\"Add company 2, 3 with new site keys and MySQL databases — same www.ecomae.com/cp/ login; email maps to the correct tenant.\"}]},\"erp-only-deployment\":{\"intro\":\"Deploy finance-led companies with no public e-commerce and no client domain — all ERP-only tenants log in at www.ecomae.com/cp/ with isolated MySQL per company.\",\"guide_area\":\"overview\",\"image\":\"guide-erp-only\",\"steps\":[{\"title\":\"Register shared ERP company\",\"body\":\"Super CP → Onboard: ERP only + Hosted on ecomae.com. Enter company name and site key only — hostname is www.ecomae.com. No DNS or domain alias.\"},{\"title\":\"Create company MySQL + CP users\",\"body\":\"One database per company (asap, company2, …). Create staff in CP → Users. Login email binds the session to that tenant DB automatically.\"},{\"title\":\"Full ERP module packs\",\"body\":\"Enable Full ERP or granular areas at onboard. Commerce, catalogue, and storefront packs stay off — sidebar is finance-first.\"},{\"title\":\"Login at www.ecomae.com/cp/\",\"body\":\"Hand off https://www.ecomae.com/cp/ or direct ERP shell URL. After login, users land in the professional ERP layout for their company only.\"},{\"title\":\"Multi-company on one URL\",\"body\":\"Repeat onboard for each new company with a unique site key and database. Optional company picker if the same email exists in two tenants.\"},{\"title\":\"Super CP stays separate\",\"body\":\"Platform operators use the same /cp/ URL with platform credentials → Tenant hub. Company users never see operator tools.\"}]},\"product-catalogue\":{\"intro\":\"Full SKU management with rich product pages, media, and category trees for fashion, electronics, medical, and general retail. Storefront and CP share the same catalogue data — no duplicate entry.\",\"guide_area\":\"commerce\",\"image\":\"guide-catalog\",\"steps\":[{\"title\":\"Open product manager\",\"body\":\"Shop → Products lists SKUs with categories, media, and stock links — same data powers storefront product pages.\"},{\"title\":\"Rich product pages\",\"body\":\"Add descriptions, images, specs, and related items — electronics get datasheet fields; fashion gets size and colour attributes.\"},{\"title\":\"Publish to storefront\",\"body\":\"Saved products appear on category trees and search immediately — no duplicate entry between CP and shop theme.\"}]},\"bulk-csv-import\":{\"intro\":\"Upload seasonal collections or thousands of SKUs via CSV — map columns, preview, and commit in minutes. Export for backup, supplier handoff, or marketplace feeds.\",\"guide_area\":\"commerce\",\"image\":\"guide-catalog\",\"steps\":[{\"title\":\"Prepare CSV template\",\"body\":\"Export a sample from Shop → Products → Export to match column order for title, SKU, category, price, and stock.\"},{\"title\":\"Upload & map columns\",\"body\":\"Import wizard maps CSV headers to product fields — preview first rows before commit.\"},{\"title\":\"Commit seasonal collections\",\"body\":\"Upload thousands of SKUs for fashion drops or electronics refreshes in minutes instead of manual entry.\"},{\"title\":\"Export for backup or feeds\",\"body\":\"Export catalogue for backup, supplier handoff, or marketplace feed generation.\"}]},\"categories-attributes\":{\"intro\":\"Merchandise with nested categories, spec filters, and custom attribute fields. Electronics get datasheet filters; fashion gets size and colour — all configurable per industry.\",\"guide_area\":\"commerce\",\"image\":\"guide-catalog\",\"steps\":[{\"title\":\"Nested category trees\",\"body\":\"Shop → Products → Categories build parent/child merchandise trees — drag order controls storefront navigation.\"},{\"title\":\"Custom attribute fields\",\"body\":\"Add spec filters for electronics, size/colour for fashion, or batch fields for medical — configurable per industry pack.\"},{\"title\":\"Storefront filters\",\"body\":\"Category and attribute filters appear on search and browse pages — shoppers narrow results without leaving the catalog.\"}]},\"variant-skus\":{\"intro\":\"Sell products with multiple variants — each with its own SKU, stock, and price. Storefront variant selectors and CP stock-by-variant keep fulfilment accurate.\",\"guide_area\":\"commerce\",\"image\":\"guide-catalog\",\"steps\":[{\"title\":\"Create variant matrix\",\"body\":\"On product edit, add size, colour, or spec variants — each variant gets its own SKU, stock row, and optional price override.\"},{\"title\":\"Storefront selectors\",\"body\":\"Shoppers pick variant options on the product page — cart and checkout carry the exact SKU for fulfilment.\"},{\"title\":\"Stock by variant\",\"body\":\"CP stock view and warehouse allocation track quantity per variant — pick lists show the correct SKU on each line.\"}]},\"supplier-price-upload\":{\"intro\":\"Keep trade pricing current by importing supplier files without manual re-keying — map columns, preview, and commit thousands of SKUs in minutes.\",\"guide_area\":\"commerce\",\"image\":\"guide-pricing\",\"steps\":[{\"title\":\"Open price upload guide\",\"body\":\"In client CP: Shop → Prices → step-by-step guide (blue button on Price lists). Describes every channel that loads data into the price database.\"},{\"title\":\"Choose upload channel\",\"body\":\"Manual CSV upload, e-mail inbox auto-import, FTP drop, or pyprices scheduled cron — each price list has a load mode configured on the list settings page.\"},{\"title\":\"Map columns & preview\",\"body\":\"Match article, brand, description, price, and stock columns to warehouse fields. Preview rows before commit to catch formatting errors.\"},{\"title\":\"Warehouse & price list link\",\"body\":\"Each price list ties to a warehouse/storage — imported stock feeds catalogue availability and live supplier price search on the storefront.\"},{\"title\":\"Verify on storefront\",\"body\":\"Search a known part number after import — trade buyers see current rates and quantity badges on results and product pages.\"}]},\"live-price-search\":{\"intro\":\"Search pulls prices from connected suppliers at order time — customers see current trade rates on the storefront. Ideal for parts traders who compete on availability and price.\",\"guide_area\":\"commerce\",\"image\":\"guide-search-parts\",\"steps\":[{\"title\":\"Connect supplier price lists\",\"body\":\"Link warehouses to imported price lists — search queries pull current trade rates at order time.\"},{\"title\":\"Storefront search results\",\"body\":\"Part number and cross-reference searches show price and quantity badges from connected lists.\"},{\"title\":\"Multi-warehouse display\",\"body\":\"When the same article exists on multiple lists, results show best price or all sources per theme configuration.\"}]},\"cross-references\":{\"intro\":\"OEM and aftermarket cross tables help customers find interchangeable parts. Cross matches against in-stock SKUs display price and quantity on the search results page.\",\"guide_area\":\"commerce\",\"image\":\"guide-search-parts\",\"steps\":[{\"title\":\"Maintain cross tables\",\"body\":\"Shop → Prices → Cross references map OEM numbers to aftermarket equivalents — import via CSV or edit inline.\"},{\"title\":\"Search integration\",\"body\":\"When a shopper searches an OEM number, cross matches against in-stock SKUs display price and quantity.\"},{\"title\":\"Reduce wrong-part orders\",\"body\":\"Workshop buyers find interchangeable parts faster — builds trust and lowers return rates.\"}]},\"vin-oem-search\":{\"intro\":\"Vehicle-aware search widgets decode VIN or accept OEM numbers for precise fitment. Reduces wrong-part orders and builds trust with workshop and fleet buyers.\",\"guide_area\":\"commerce\",\"image\":\"guide-search-parts\",\"steps\":[{\"title\":\"Enable search widgets\",\"body\":\"Storefront search bar accepts VIN decode or direct OEM/part number entry — auto-parts themes ship with vehicle-aware widgets.\"},{\"title\":\"VIN decode flow\",\"body\":\"Decoded VIN narrows make, model, and engine — catalogue browse filters to compatible articles.\"},{\"title\":\"OEM number lookup\",\"body\":\"Enter manufacturer part number for precise fitment — results cross-match to in-stock SKUs with live pricing.\"}]},\"vehicle-catalogue\":{\"intro\":\"Browse by make, model, and modification — Epart catalog integration for passenger, commercial, and motorbike segments. Product groups and articles flow into cart and ERP.\",\"guide_area\":\"commerce\",\"image\":\"guide-search-parts\",\"steps\":[{\"title\":\"Open Epart catalog\",\"body\":\"Shoppers browse by make, model, and modification — passenger, commercial, and motorbike segments from integrated eparts catalog.\"},{\"title\":\"Product groups & articles\",\"body\":\"OEM-style categories, technical measurements, and article pages flow into cart and order desk without duplicate data entry.\"},{\"title\":\"Vehicle catalog route\",\"body\":\"Optional vehicle catalog page lets buyers pick year → make → model → engine before viewing compatible articles and in-stock prices.\"}]},\"price-lists-margins\":{\"intro\":\"Segment B2B and retail buyers with customer groups, price profiles, and margin rules — retail shelf prices, wholesale CIS/GCC margins, and brand visibility controls from one CP screen.\",\"guide_area\":\"commerce\",\"image\":\"guide-pricing\",\"steps\":[{\"title\":\"Customer groups & profiles\",\"body\":\"Shop → Customers → Groups and Profiles assign each buyer a segment. Profiles drive which brands and categories appear after login and which margin rule applies.\"},{\"title\":\"Retail vs wholesale margins\",\"body\":\"Configure retail mark-up and wholesale discount tiers per profile — CIS and GCC trade accounts can have separate margin tables and fixed dealing currency.\"},{\"title\":\"Price list assignment\",\"body\":\"Link customer profiles to price lists (S-UAE, R-UAE, etc.) so logged-in trade buyers see contract rates while guests see standard shelf pricing.\"},{\"title\":\"Show/hide by brand\",\"body\":\"Hide premium or restricted brands from retail profiles while exposing full catalog to approved wholesale accounts — useful for distributor and medical verticals.\"},{\"title\":\"Upload wizard & pyprices\",\"body\":\"Refresh underlying price lists via Shop → Prices → upload guide — CSV upload, e-mail inbox, FTP, or pyprices cron. Imported rows feed live search and profile-driven margins instantly.\"}]},\"shopping-cart-checkout\":{\"intro\":\"Guest and logged-in checkout with delivery choice, promo codes, and payment at checkout. Orders flow straight into CP order desk and ERP finance — one data path end to end.\",\"guide_area\":\"commerce\",\"image\":\"guide-checkout\",\"steps\":[{\"title\":\"Guest or logged-in cart\",\"body\":\"Storefront cart persists for logged-in buyers; guests checkout with e-mail capture — promo codes apply at cart review.\"},{\"title\":\"Delivery & payment choice\",\"body\":\"Checkout selects obtaining mode, payment type, and contact details — credit limits enforced for trade accounts.\"},{\"title\":\"Order creation\",\"body\":\"Confirmed checkout saves to order desk — manager, customer, and supplier LPO notifications fire automatically.\"},{\"title\":\"ERP handoff\",\"body\":\"Completed orders feed ERP Revenue and receivables — one data path from storefront to finance.\"}]},\"order-management\":{\"intro\":\"Staff manage order lifecycle from new through packed, shipped, and completed. Status updates trigger customer emails and feed fulfilment and finance modules.\",\"guide_area\":\"commerce\",\"image\":\"guide-fulfilment\",\"steps\":[{\"title\":\"Orders list filters\",\"body\":\"Shop → Orders — filter by status, office, payment type, article, or date range to find work in the queue.\"},{\"title\":\"Order card intelligence\",\"body\":\"Open order number for customer profile, margin totals, line statuses, messages, and order log history.\"},{\"title\":\"Status-driven e-mails\",\"body\":\"Configure order and line statuses in Shop → Orders → Statuses — each status can notify manager and/or customer.\"},{\"title\":\"Payment confirmation\",\"body\":\"Record payment on the order card or via Finance — advance order status when fully paid.\"}]},\"order-fulfilment\":{\"intro\":\"Move every web order from checkout to supplier LPO, warehouse pick/pack, and ERP recognition without leaving the control panel. Warehouse-aware fulfilment keeps stock, finance, and customer notifications in sync.\",\"guide_area\":\"commerce\",\"image\":\"guide-fulfilment\",\"steps\":[{\"title\":\"Order desk pipeline\",\"body\":\"New web orders land in Shop → Orders. Staff advance statuses from confirmed through packed and shipped — customer e-mails fire on each configured status change.\"},{\"title\":\"Trade approval before checkout\",\"body\":\"Wholesale buyers register on the storefront; checkout stays blocked until CP approves the account and assigns a fixed dealing currency under Users → Customer approvals.\"},{\"title\":\"Automatic checkout notifications\",\"body\":\"On order creation, three channels fire: manager alert with CP link, customer confirmation, and supplier LPO e-mail per warehouse — configure templates in Control panel → Notifications.\"},{\"title\":\"Supplier LPO per warehouse\",\"body\":\"Each warehouse with order lines receives a purchase request — LPO number equals the customer order ID. Set Supplier order email on Shop → Logistics → Warehouses before go-live.\"},{\"title\":\"Pick, pack & line statuses\",\"body\":\"On the order card, confirm payment, update line item statuses (ordered → in stock → shipped → delivered), and message the customer from the Messages tab.\"},{\"title\":\"Delivery notes & obtaining modes\",\"body\":\"Generate delivery notes from confirmed orders and configure pickup or courier modes in Shop → Logistics → Obtaining modes. Print-ready documents include line items and delivery details.\"},{\"title\":\"ERP fulfilment tab\",\"body\":\"Shop → ERP Finance → Fulfilment shows the visual pipeline: customer payment → supplier payment → goods in stock → delivery → returns. Revenue and payables post when the order is Completed.\"},{\"title\":\"Returns & partial shipments\",\"body\":\"Process returns in CP returns module — goods return to stock then to supplier if needed. Partial shipments stay traceable via line-level statuses and order log entries.\"}]},\"delivery-notes\":{\"intro\":\"Generate delivery notes and pick lists from confirmed orders — print-ready documents with line items, weights, and customer delivery details.\",\"guide_area\":\"commerce\",\"image\":\"guide-fulfilment\",\"steps\":[{\"title\":\"Generate from confirmed order\",\"body\":\"On order card, print delivery note with line items, weights, and customer delivery address.\"},{\"title\":\"Pick list alignment\",\"body\":\"Pick lists group warehouse lines for floor staff — same SKU and quantity as delivery note for audit.\"},{\"title\":\"Branded PDF output\",\"body\":\"Document templates merge company logo, TRN footer, and bank details — consistent with invoice layouts.\"}]},\"returns-rma\":{\"intro\":\"Process returns and warranty claims with status tracking and stock put-back. Electronics and medical verticals get serial and batch fields for audit-friendly RMA.\",\"guide_area\":\"commerce\",\"image\":\"guide-fulfilment\",\"steps\":[{\"title\":\"Customer initiates return\",\"body\":\"Storefront returns form or CP manual RMA captures reason, serial/batch if required, and linked order lines.\"},{\"title\":\"RMA status tracking\",\"body\":\"Staff advance return statuses — received, inspected, credited — with optional customer e-mail on each step.\"},{\"title\":\"Stock put-back\",\"body\":\"Approved returns increment warehouse stock; credit notes link to original tax invoice for VAT audit trail.\"}]},\"whatsapp-order-share\":{\"intro\":\"Share cart or order summaries via WhatsApp for quick B2B confirmation. Popular with UAE and GCC traders who close deals on mobile messaging.\",\"guide_area\":\"commerce\",\"image\":\"guide-checkout\",\"steps\":[{\"title\":\"Share from cart or order\",\"body\":\"Storefront share button sends cart summary or order confirmation via WhatsApp deep link — popular with UAE B2B traders.\"},{\"title\":\"Mobile-friendly format\",\"body\":\"Shared message includes part numbers, quantities, and totals for quick buyer confirmation on mobile.\"},{\"title\":\"Close on messaging\",\"body\":\"Counter staff follow up in WhatsApp then convert to CP order if the buyer confirms — same fulfilment pipeline applies.\"}]},\"promo-discount-rules\":{\"intro\":\"Campaign promo codes, cart rules, and tiered discounts drive conversion on the storefront. Link promotions to marketing campaigns for measurable uplift.\",\"guide_area\":\"commerce\",\"image\":\"guide-checkout\",\"steps\":[{\"title\":\"Create promo codes\",\"body\":\"Shop → Marketing → Promotions define codes, percentage or fixed discount, date range, and minimum cart value.\"},{\"title\":\"Cart rules & tiers\",\"body\":\"Tiered discounts apply automatically when cart crosses thresholds — link campaigns to UTM landing pages for measurement.\"},{\"title\":\"Storefront application\",\"body\":\"Shoppers enter code at checkout or see auto-applied tier — discount flows to order totals and ERP revenue.\"}]},\"b2b-trade-accounts\":{\"intro\":\"Logged-in trade buyers get fixed currency, credit limits, balance view, and re-order from history. Auto-parts and wholesale tenants rely on this for repeat B2B cycles.\",\"guide_area\":\"commerce\",\"image\":\"guide-checkout\",\"steps\":[{\"title\":\"Wholesale registration\",\"body\":\"Buyers choose Wholesale at registration — checkout blocked until CP approves under Users → Customer approvals.\"},{\"title\":\"Fixed currency & credit\",\"body\":\"Assign dealing currency and credit limit on approval — balance and limit visible in client CP login.\"},{\"title\":\"Re-order from history\",\"body\":\"Logged-in trade buyers re-order from past invoices — contract pricing from their profile applies automatically.\"}]},\"payment-gateways\":{\"intro\":\"Configure card and local payment gateways for UAE and GCC checkout. Gateway settings live in CP — test mode and live credentials per tenant.\",\"guide_area\":\"payments\",\"image\":\"guide-payments\",\"steps\":[{\"title\":\"Open payments guide\",\"body\":\"Shop → Finance → Payments guide walks gateway setup for UAE and GCC card and local payment methods.\"},{\"title\":\"Test vs live credentials\",\"body\":\"Enter merchant ID, API keys, and webhook URLs — toggle test mode before go-live checkout.\"},{\"title\":\"Checkout integration\",\"body\":\"Enabled gateways appear at storefront checkout — successful payments mark order paid and trigger notifications.\"}]},\"multi-currency\":{\"intro\":\"Show prices and accept payment in multiple currencies for cross-border and tourist retail. Exchange display rules configurable per storefront theme.\",\"guide_area\":\"payments\",\"image\":\"guide-payments\",\"steps\":[{\"title\":\"Configure display currencies\",\"body\":\"Shop → Settings → Currencies add AED, USD, SAR, and others — set display rules per storefront theme.\"},{\"title\":\"Checkout currency\",\"body\":\"Logged-in trade buyers checkout in assigned dealing currency; tourist retail can show converted display prices.\"},{\"title\":\"ERP reporting\",\"body\":\"Finance reports remain in base currency with order-level currency captured for audit.\"}]},\"payment-reconciliation\":{\"intro\":\"Match gateway settlements to orders and ERP receipts — reduce manual spreadsheet work for finance teams. Discrepancies surface in CP for quick resolution.\",\"guide_area\":\"payments\",\"image\":\"guide-payments\",\"steps\":[{\"title\":\"Import gateway settlements\",\"body\":\"Match gateway batch files to CP orders — unmatched items surface for finance review.\"},{\"title\":\"ERP receipt posting\",\"body\":\"Confirmed matches post customer receipts in ERP Cash & bank — reduces manual spreadsheet reconciliation.\"},{\"title\":\"Discrepancy resolution\",\"body\":\"Short payments and chargebacks flag on order card for staff follow-up before month-end close.\"}]},\"customer-balance-credit\":{\"intro\":\"Track trade account balances and enforce credit limits at checkout. B2B clients see running balance in client CP; staff approve overrides in order desk.\",\"guide_area\":\"payments\",\"image\":\"guide-payments\",\"steps\":[{\"title\":\"Prepaid ledger\",\"body\":\"Shop → Finance → Customer accounts track credit top-ups and order debits per trade buyer.\"},{\"title\":\"Credit limit at checkout\",\"body\":\"Checkout blocks orders exceeding available balance plus approved credit limit — staff override in order desk if needed.\"},{\"title\":\"Client CP balance view\",\"body\":\"Logged-in B2B clients see running balance and recent movements on storefront account page.\"}]},\"payment-batches\":{\"intro\":\"Batch outgoing supplier and expense payments from ERP treasury — approve, schedule, and audit payment runs from finance roles.\",\"guide_area\":\"payments\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"Open ERP treasury\",\"body\":\"Shop → ERP Finance → Cash & bank — create payment batch for supplier or expense runs.\"},{\"title\":\"Approve & schedule\",\"body\":\"Finance role selects payables lines, approves batch, and schedules settlement date.\"},{\"title\":\"Audit trail\",\"body\":\"Batch history logs who approved, which suppliers paid, and GL postings for month-end audit.\"}]},\"warehouses-storages\":{\"intro\":\"Master warehouse and storage locations with stock allocation per site. Multi-warehouse inventory feeds catalogue availability and checkout delivery options.\",\"guide_area\":\"logistics\",\"image\":\"guide-logistics\",\"steps\":[{\"title\":\"Master warehouse list\",\"body\":\"Shop → Logistics → Warehouses defines storage locations, linked price lists, and LPO supplier e-mail per site.\"},{\"title\":\"Stock allocation\",\"body\":\"Each SKU row ties to a warehouse — catalogue availability and checkout delivery options reflect per-site quantity.\"},{\"title\":\"Multi-warehouse orders\",\"body\":\"Orders with lines from multiple warehouses trigger separate supplier LPO e-mails — one per warehouse.\"}]},\"carriers-shipments\":{\"intro\":\"Manage carrier accounts, shipment creation, and tracking references. Logistics hub ties customer orders to outbound shipments and delivery documentation.\",\"guide_area\":\"logistics\",\"image\":\"guide-logistics\",\"steps\":[{\"title\":\"Carrier accounts\",\"body\":\"Logistics hub stores carrier API credentials and service codes — create shipment from confirmed order.\"},{\"title\":\"Tracking references\",\"body\":\"Outbound shipments capture AWB or tracking number — customer notification optional on dispatch status.\"},{\"title\":\"Delivery documentation\",\"body\":\"Shipment links to delivery note and order card — logistics reports show carrier performance.\"}]},\"delivery-methods\":{\"intro\":\"Configure courier, branch pickup, and service-area rules on the storefront. Customers choose delivery at checkout; lead times display on SKU where configured.\",\"guide_area\":\"logistics\",\"image\":\"guide-logistics\",\"steps\":[{\"title\":\"Obtaining modes\",\"body\":\"Shop → Logistics → Obtaining modes configure courier, branch pickup, and service-area delivery rules.\"},{\"title\":\"Checkout selection\",\"body\":\"Customers choose delivery or pickup at checkout — lead times display on SKU where configured.\"},{\"title\":\"Fee rules\",\"body\":\"Flat or weight-based delivery fees apply per mode — free delivery thresholds configurable per campaign.\"}]},\"branch-offices\":{\"intro\":\"Maintain branch offices and pickup points shown on storefront and delivery notes. Useful for multi-location retailers and parts distributors with counter collection.\",\"guide_area\":\"logistics\",\"image\":\"guide-logistics\",\"steps\":[{\"title\":\"Branch master data\",\"body\":\"Maintain branch name, address, hours, and map coordinates — shown on storefront contact and pickup selector.\"},{\"title\":\"Pickup at branch\",\"body\":\"Link branches to obtaining modes — delivery notes and e-mails show collection point details.\"},{\"title\":\"Multi-location retail\",\"body\":\"Fashion and parts distributors display nearest counter for click-and-collect orders.\"}]},\"logistics-reports\":{\"intro\":\"Operational reports on fulfilment throughput, carrier performance, and stock by location. Export-friendly views for warehouse managers and operators.\",\"guide_area\":\"logistics\",\"image\":\"guide-logistics\",\"steps\":[{\"title\":\"Fulfilment throughput\",\"body\":\"Reports show orders packed and shipped by period, warehouse, and carrier — export for warehouse managers.\"},{\"title\":\"Stock by location\",\"body\":\"Inventory snapshot per warehouse supports replenishment decisions and cycle counts.\"},{\"title\":\"Carrier performance\",\"body\":\"Delivery SLA and exception counts help negotiate carrier contracts.\"}]},\"custom-shipping-declarations\":{\"intro\":\"UAE customs declaration registry mapped from the C&L Excel format — 36 declaration types across import, export, transit, temporary admission, and transfer, plus LGP warehouse intake. Dashboard KPIs, category lists, core field capture, and Phase 2 reports (search, cost summary, duty stub, re-export, document expiry) are live in ERP.\",\"guide_area\":\"logistics\",\"image\":\"guide-custom-shipping\",\"steps\":[{\"title\":\"Open Custom & Shipping dashboard\",\"body\":\"In client CP go to ERP Suite → Custom & Shipping (sidebar group) or Shop → Finance → ERP with area custom_shipping. The dashboard shows total, draft, submitted, and cleared counts plus six category cards.\"},{\"title\":\"Review declaration categories\",\"body\":\"Import (12 types), Export (13), Transit (6), Temporary Admission (3), Transfer (2), and LGP warehouse intake each have their own card with live counts. Click a card to list declarations in that category.\"},{\"title\":\"Start from quick action or type list\",\"body\":\"Use quick actions for Import to Local from ROW, Export from Local to ROW, FZ transit in, or New LGP entry — or open a category and pick any of the 36 registered declaration types from the Excel workbook.\"},{\"title\":\"Fill core required fields\",\"body\":\"Every customs declaration requires Company, Customs emirate (Dubai, Sharjah, Abu Dhabi, etc.), Declaration type, Date, and Declaration date. Add B/L #, SRV #, supplier detail, currency, and invoice amount from your customs paperwork.\"},{\"title\":\"Import workflow fields\",\"body\":\"Import declarations add supplier code (customs), custom inspection flag, and D365 PO reference — matching the Excel import columns for local, FZ, CW, and courier entries.\"},{\"title\":\"Multiple HS code line items\",\"body\":\"Use the declaration line items grid to add one row per HS code: country of origin, quantity, unit (PCS, KG, etc.), volume (CBM), amount, and optional weight. Totals sum qty, volume, and amount; lists show item count per declaration.\"},{\"title\":\"Export, transit & transfer fields\",\"body\":\"Export, transit, temporary admission, and transfer types capture import (re-export) declaration ref #, document expiry date, D365 SO reference, customer ref, and customer country where applicable on re-export and return flows.\"},{\"title\":\"LGP warehouse intake\",\"body\":\"LGP entries use a dedicated form: customer ref, cargo source, goods coming from, warehouse name/number, local company, purpose of entry, packing list, and commercial invoice are required. Use line items for multiple HS codes, weights, volumes, and values.\"},{\"title\":\"Save draft and submit\",\"body\":\"Click Save draft while paperwork is in progress. Open the saved record from the category list, review captured fields, then Submit when filed with UAE customs. Status flows draft → submitted → cleared.\"},{\"title\":\"Run declaration reports\",\"body\":\"Open Reports from the Custom & Shipping dashboard. Use Declaration search to filter by date, type, category, company, emirate, and status — or search by declaration #, supplier, and SRV/shipment no. Export CSV or print results.\"},{\"title\":\"Cost summary and duty stub\",\"body\":\"Cost summary aggregates invoice amount, total cost, and line-item amounts by company and category. Duty report lists HS codes and origins per line with declaration totals — full duty calculation arrives in a later phase.\"},{\"title\":\"Re-export and document expiry\",\"body\":\"Re-export tracking shows import-for-re-export and re-export declarations with links to the original import ref #. Document expiry lists overdue and upcoming expiry dates within a configurable day window.\"}]},\"omnichannel-hub\":{\"intro\":\"Central hub for selling beyond your own storefront — connect marketplaces and sales channels from one CP screen. Orders from all channels land in the same order desk.\",\"guide_area\":\"channels\",\"image\":\"guide-channels\",\"steps\":[{\"title\":\"Open channels hub\",\"body\":\"Shop → Channels centralises marketplace and aggregator connections — one screen for all non-web sales routes.\"},{\"title\":\"Unified order desk\",\"body\":\"Orders from every connected channel land in the same Shop → Orders queue — no separate middleware inbox.\"},{\"title\":\"Shared inventory truth\",\"body\":\"Catalogue and stock updates push to channels — reduce overselling with single warehouse allocation.\"}]},\"channel-integrations\":{\"intro\":\"Enable marketplace and aggregator integrations per industry pack. Fashion, electronics, and auto-parts tenants extend reach without separate middleware hosting.\",\"guide_area\":\"channels\",\"image\":\"guide-channels\",\"steps\":[{\"title\":\"Enable channel pack\",\"body\":\"Industry settings enable marketplace integrations per vertical — fashion, electronics, and auto-parts packs differ.\"},{\"title\":\"Connect credentials\",\"body\":\"Enter marketplace API keys and seller IDs in Channels guide — test listing before production sync.\"},{\"title\":\"Operator fix queue\",\"body\":\"Listing errors surface in Channels guide for operator correction without developer tickets.\"}]},\"marketplace-listings\":{\"intro\":\"Push catalogue and stock updates to connected channels — reduce overselling with shared inventory truth. Listing errors surface in channels guide for operator fix.\",\"guide_area\":\"channels\",\"image\":\"guide-channels\",\"steps\":[{\"title\":\"Catalogue sync\",\"body\":\"Push active SKUs, titles, images, and stock levels to connected marketplaces on schedule or on demand.\"},{\"title\":\"Price rules per channel\",\"body\":\"Optional channel-specific margin or rounding rules — base price from same CP catalogue.\"},{\"title\":\"Error monitoring\",\"body\":\"Failed listing updates log in Channels hub — fix category mapping or attribute gaps in CP.\"}]},\"channel-order-routing\":{\"intro\":\"External channel orders route into the same fulfilment and ERP pipeline as web orders. One pick/pack workflow regardless of where the sale originated.\",\"guide_area\":\"channels\",\"image\":\"guide-channels\",\"steps\":[{\"title\":\"Inbound order import\",\"body\":\"Marketplace orders import with channel reference — line items map to warehouse SKUs automatically.\"},{\"title\":\"Same fulfilment pipeline\",\"body\":\"Pick, pack, LPO, and ERP recognition follow identical steps as web orders — staff need one workflow.\"},{\"title\":\"Status sync back\",\"body\":\"Shipped and delivered statuses optionally push tracking back to the originating channel.\"}]},\"supplier-directory\":{\"intro\":\"Maintain supplier master data — contacts, terms, and linked price files. Auto-parts and wholesale tenants manage dozens of suppliers from one procurement hub.\",\"guide_area\":\"procurement\",\"image\":\"guide-procurement\",\"steps\":[{\"title\":\"Procurement hub\",\"body\":\"Shop → Procurement → Suppliers maintains legal name, TRN, contacts, payment terms, and linked warehouses.\"},{\"title\":\"Price list association\",\"body\":\"Link supplier to price lists for LPO routing — operational purchasing separate from warehouse stock source.\"},{\"title\":\"Dozens of suppliers\",\"body\":\"Auto-parts and wholesale tenants manage full supplier roster without spreadsheet master data.\"}]},\"purchase-orders\":{\"intro\":\"Create and track POs from requisition through receipt. PO lines link to ERP payables and three-way match when finance pack is active.\",\"guide_area\":\"procurement\",\"image\":\"guide-procurement\",\"steps\":[{\"title\":\"Create PO\",\"body\":\"Procurement → Purchase orders — add lines from requisition or generate from low-stock signals.\"},{\"title\":\"Approval workflow\",\"body\":\"Draft → approved → sent → received statuses track buy-side lifecycle with e-mail to supplier optional.\"},{\"title\":\"ERP payables link\",\"body\":\"Received PO lines feed ERP payables and three-way match when finance pack is active.\"}]},\"rfq-quotes\":{\"intro\":\"Request quotes from multiple suppliers and compare responses before committing to a PO. Built for project-based and MRO procurement workflows.\",\"guide_area\":\"procurement\",\"image\":\"guide-procurement\",\"steps\":[{\"title\":\"Issue RFQ\",\"body\":\"Create request for quote with line specs — send to multiple suppliers from procurement hub.\"},{\"title\":\"Compare responses\",\"body\":\"Record supplier quotes side by side — select winner and convert to PO in one click.\"},{\"title\":\"Project & MRO buying\",\"body\":\"Built for project-based procurement where price and lead time vary by supplier bid.\"}]},\"three-way-match\":{\"intro\":\"Match purchase order, goods receipt, and supplier invoice before payment approval. Reduces duplicate payments and catches quantity or price variances early.\",\"guide_area\":\"procurement\",\"image\":\"guide-procurement\",\"steps\":[{\"title\":\"Three documents\",\"body\":\"Match purchase order, goods receipt note (GRN), and supplier invoice quantities and prices before payment.\"},{\"title\":\"Variance flags\",\"body\":\"Quantity or price mismatches block payment approval — finance resolves with procurement before posting.\"},{\"title\":\"Reduce duplicate pay\",\"body\":\"Catches double billing and short shipments early — audit-friendly for UAE trading entities.\"}]},\"supplier-payments\":{\"intro\":\"Track amounts owed to suppliers and schedule settlement from ERP payables tab. Aging reports help finance prioritise cash outflows.\",\"guide_area\":\"procurement\",\"image\":\"guide-procurement\",\"steps\":[{\"title\":\"Payables aging\",\"body\":\"ERP → Supplier payables shows amounts owed by supplier and due date — aging report prioritises cash outflows.\"},{\"title\":\"Record payment\",\"body\":\"Post supplier payment from payables tab — reduces balance and posts cash/bank GL entry automatically.\"},{\"title\":\"Payment batches\",\"body\":\"Group multiple supplier payments into treasury batch for single bank transfer and approval run.\"}]},\"procurement-workflows\":{\"intro\":\"End-to-end buy-side process from demand signal through PO, receipt, and invoice. Integrated with auto-parts SAO and ERP purchasing areas.\",\"guide_area\":\"procurement\",\"image\":\"guide-procurement\",\"steps\":[{\"title\":\"Demand to PO\",\"body\":\"Low stock, SAO signals, or manual requisition start the buy-side process in Procurement panel.\"},{\"title\":\"Receipt & GRN\",\"body\":\"Goods receipt updates warehouse stock and feeds three-way match when supplier invoice arrives.\"},{\"title\":\"Auto-parts SAO integration\",\"body\":\"API warehouse lines may trigger supplier auto-order workflows alongside LPO e-mail path.\"}]},\"erp-dashboard\":{\"intro\":\"One finance dashboard for revenue, margin, receivables, payables, and cash — plus a cross-department workflow view for growing UAE trading businesses.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"Open ERP Finance\",\"body\":\"Client CP → Shop → ERP Finance. Set From/To dates and review KPI cards: revenue MTD, margin, receivable due, payable balance, and cash total.\"},{\"title\":\"Sales → revenue → receivable flow\",\"body\":\"Completed orders feed Revenue tab; customer payments reduce receivable; prepaid ledger balance shows on Customer receivables with per-customer statements.\"},{\"title\":\"Purchase → payable → cash flow\",\"body\":\"Procurement purchase bills increase supplier payable; Record supplier payment posts cash outflow and reduces AP — all visible on Payables and Cash & bank tabs.\"},{\"title\":\"COA, GL, P&L & balance sheet\",\"body\":\"Chart of accounts lists assets through expenses; GL journals post from orders and manual entries; P&L and Balance sheet tabs export period reports for advisors.\"},{\"title\":\"Fulfilment & inventory tabs\",\"body\":\"Fulfilment pipeline visualises operations stages; Inventory tab tracks multi-warehouse weighted average cost with purchase receipts and sales issues.\"},{\"title\":\"CRM inside ERP\",\"body\":\"Pipeline kanban, quotes, and support tickets live in the same ERP module — consultancies run sales and billing without a separate CRM subscription.\"}]},\"business-unit-dimensions\":{\"intro\":\"D365-style financial dimensions — business unit, cost centre, department, project and custom tenant dimensions — selectable on every entry so clients segregate and report results by any dimension combination.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"Define dimensions once\",\"body\":\"Enterprise → Business unit sets up business units, cost centres, departments, projects and any custom financial dimensions in the tenant master — nothing is hard-coded.\"},{\"title\":\"Tag on every entry\",\"body\":\"The dimension picker appears on sales orders, purchase orders, customers, vendors, invoices, receipt & payment vouchers, journals, inventory items, listings and more — pick the business unit and sub-dimensions when you create the record.\"},{\"title\":\"See it on lists\",\"body\":\"Saved dimensions show as badges in list/grid views (e.g. a sales order tagged \\\"Retail Division / Sales\\\") so you can scan segregation at a glance.\"},{\"title\":\"Report by dimension\",\"body\":\"Trial balance, consolidation and dimension reporting slice results by business unit and any dimension combination — shared COA across all business units.\"}]},\"enterprise-modules-d365\":{\"intro\":\"Fourteen config-driven enterprise modules with sub-modules, each writing to the tenant's own database — no storefront required for an ERP-only client.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"Enterprise area in the nav\",\"body\":\"The ERP shell adds Business unit, Listing, Budgeting, Consolidation and Reporting under Enterprise; the rest slot into Sales, Purchasing, Finance and Operations.\"},{\"title\":\"Per-tenant, config-driven\",\"body\":\"Each module and sub-module is driven by per-tenant configuration — enable only what a client licenses, with masters seeded from the chosen industry pack.\"},{\"title\":\"Standalone create\",\"body\":\"Create a business unit, item, budget or document entirely inside ERP — it instantly appears in dependent dropdowns (Budgeting, Trial balance) without touching e-commerce.\"}]},\"netsuite-d365-ux\":{\"intro\":\"NetSuite-style role dashboard with a Dynamics 365 Finance & Operations inner experience across every module.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"NetSuite-style home\",\"body\":\"The landing dashboard uses tiles, a KPI gauge, an A/R aging chart, reminders and visual quick-action cards (New sales order, New item, Receipt voucher, VAT return).\"},{\"title\":\"D365 sliding nav\",\"body\":\"The left pane is a D365 navigation tree grouped into Common / Journals / Inquiries / Setup / Periodic, and collapses to an icon rail with flyout submenus.\"},{\"title\":\"Action pane & FastTabs\",\"body\":\"Entry forms use a top action-pane command bar (New / Save) and collapsible FastTab sections; list pages use the grid styling with a hyperlink first column.\"}]},\"period-asof-reporting\":{\"intro\":\"True point-in-time ERP reporting reconstructed from dated movement ledgers, with a per-tenant fiscal calendar driving every year.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"As-at single date\",\"body\":\"Inventory → Stock in hand has an \\\"Inventory on hand as at [date]\\\" picker that replays each receipt and issue to that day for historical quantity, weighted-average cost and value.\"},{\"title\":\"From/To period flows\",\"body\":\"P&L, ledgers, sales/purchase lists and bank transaction reports use a From/To period bar; master/setup screens have no date bar, following standard ERP rules.\"},{\"title\":\"Fiscal calendar\",\"body\":\"A per-tenant fiscal-year/period calendar lets you pick FY2024, FY2025 or a month for closing snapshots across every year.\"}]},\"aging-statements\":{\"intro\":\"Config-driven AR / AP / inventory aging plus customer and vendor statements of account on tenant letterhead.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"Aging by bucket\",\"body\":\"Finance → Aging shows Receivables, Payables and Inventory aging with per-bucket totals and a distribution bar — bucket sizes come from Accounting setup, nothing hard-coded.\"},{\"title\":\"Statement of account\",\"body\":\"Generate a customer or vendor statement rendered with the tenant letterhead, logo and TRN for collections and audit.\"},{\"title\":\"Drill to documents\",\"body\":\"Each aged balance ties back to its source invoices, receipts and payments for fast reconciliation.\"}]},\"general-ledger\":{\"intro\":\"Double-entry GL with journal entries, period close, and audit-friendly posting history. Commerce and ERP share customer and SKU master data — no re-keying invoices.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-gl\",\"steps\":[{\"title\":\"GL journal list\",\"body\":\"ERP → GL tab shows posted journals with debit/credit lines — filter by date and source document.\"},{\"title\":\"Auto-post from sub-ledgers\",\"body\":\"Sales orders, purchase bills, and cash entries post balanced journals — Sync unposted catches backlog.\"},{\"title\":\"Manual journals\",\"body\":\"Finance enters balanced debit/credit lines for adjustments — Post journal writes to GL with audit user stamp.\"}]},\"chart-of-accounts\":{\"intro\":\"Configure COA structure for UAE trading, services, and multi-department businesses. Opening balances migration supported for tenants moving from spreadsheets.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-gl\",\"steps\":[{\"title\":\"COA structure\",\"body\":\"ERP → Chart of accounts lists codes: assets 1xxx, liabilities 2xxx, equity 3xxx, revenue 4xxx, expenses 5xxx/6xxx.\"},{\"title\":\"UAE trading defaults\",\"body\":\"Industry template seeds COA suited to UAE trading and services — edit or extend per department.\"},{\"title\":\"Opening balances\",\"body\":\"Opening balances tab supports migration date cutover from spreadsheets or prior system.\"}]},\"cash-bank-treasury\":{\"intro\":\"Manage bank accounts, petty cash, and treasury movements in one finance area. Payment batches and reconciliation tie back to GL automatically.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"Bank accounts\",\"body\":\"ERP → Cash & bank — create main cash, current accounts, and petty cash with opening balances.\"},{\"title\":\"Receipts & payments\",\"body\":\"Post customer receipts and expense payments — supplier payments auto-post from payables module.\"},{\"title\":\"Account balance\",\"body\":\"Running balance = opening + receipts − payments — ties to GL cash accounts on reconciliation.\"}]},\"bank-reconciliation\":{\"intro\":\"Match bank statement lines to ERP receipts and payments — flag unmatched items for review. Monthly recon workflow keeps books aligned with actual cash.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-gl\",\"steps\":[{\"title\":\"Import statement\",\"body\":\"Upload or enter bank statement lines for the period — unmatched ERP entries highlight in review queue.\"},{\"title\":\"Match lines\",\"body\":\"Link statement lines to ERP receipts and payments — flag items needing investigation.\"},{\"title\":\"Monthly close\",\"body\":\"Reconciled accounts confirm books align with actual cash before P&L and VAT reporting.\"}]},\"receivables\":{\"intro\":\"Track customer invoices, receipts, and aging from sales orders through collection. B2B trade balances sync with storefront client login where configured.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"Customer receivables tab\",\"body\":\"ERP lists customers with ledger balance and open order due — click Statement for full history.\"},{\"title\":\"Order-level due\",\"body\":\"Revenue tab shows unpaid completed orders incl. VAT — payments reduce due on order card or finance ops.\"},{\"title\":\"Adjustments & write-offs\",\"body\":\"Customer adjustment form handles settlements and write-offs with optional GL post to AR accounts.\"}]},\"inventory-valuation\":{\"intro\":\"Multi-warehouse stock with purchase receipts, sales issues, and weighted average costing. Perishable expiry and batch fields for FMCG and medical supplies.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"Multi-warehouse stock\",\"body\":\"ERP → Inventory shows quantity and weighted average cost per warehouse and SKU.\"},{\"title\":\"Purchase receipts\",\"body\":\"Goods receipt increases stock and updates average cost — sales issues reduce quantity on shipment.\"},{\"title\":\"Batch & expiry\",\"body\":\"Medical and FMCG packs add batch and expiry fields — FEFO picking supported in fulfilment workflow.\"}]},\"fixed-assets\":{\"intro\":\"Asset register with straight-line and declining depreciation, monthly runs, and net book value reports. Tracking IDs and locations support audit and fleet operators.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"Asset register\",\"body\":\"ERP → Fixed assets — add assets with cost, useful life, location, and tracking ID.\"},{\"title\":\"Depreciation run\",\"body\":\"Straight-line or declining methods — monthly run posts depreciation to GL and updates net book value.\"},{\"title\":\"NBV reports\",\"body\":\"Export asset schedule for auditors and fleet operators — disposal workflow removes from register.\"}]},\"pl-balance-sheet\":{\"intro\":\"Standard financial statements from posted GL — filter by period and export for advisors. Tax firms use this alongside VAT return data for client reporting.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"P&L tab\",\"body\":\"Select period — total revenue minus expenses equals net profit; drill to GL account detail.\"},{\"title\":\"Balance sheet\",\"body\":\"Assets, liabilities, and equity as of end date — current period earnings included in equity.\"},{\"title\":\"Export for advisors\",\"body\":\"Filter by period and export — tax firms combine with VAT return data for client reporting.\"}]},\"erp-workflow\":{\"intro\":\"Visual workflow across sales, purchasing, finance, and operations — see bottlenecks before month-end. Native ERP tabs replace disconnected spreadsheets for growing tenants.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"Cross-department view\",\"body\":\"ERP workflow tab visualises sales, purchasing, finance, and operations stages — spot bottlenecks before month-end.\"},{\"title\":\"Native ERP tabs\",\"body\":\"Replace disconnected spreadsheets — revenue, payables, inventory, and CRM share one database.\"},{\"title\":\"Standalone /erp portal\",\"body\":\"Optional client finance portal at /erp for teams who need finance access without full CP.\"}]},\"multi-company-erp-access\":{\"intro\":\"One hosted tenant serves multiple legal entities — each staff user signs in with username and password, company-scoped customs data and reports stay separate, and ERP tabs respect department roles.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-erp-finance\",\"steps\":[{\"title\":\"Create users per company team\",\"body\":\"Control panel → Users → add finance, logistics, and customs staff with individual username/password credentials. Assign backend groups for admin, finance, warehouse, or read-only roles.\"},{\"title\":\"Role-based ERP tabs\",\"body\":\"After sign-in at /erp or the ERP shell, users see only permitted areas — GL, payables, Custom & Shipping, and reports based on their group membership.\"},{\"title\":\"Company field on declarations\",\"body\":\"Custom & Shipping captures Company on every customs entry — import, export, transit, LGP, and transfer forms all require the legal entity name for multi-company tracking.\"},{\"title\":\"Filter reports by company\",\"body\":\"Open Custom & Shipping → Reports → Declaration search. Set the company filter (cs_company) to isolate one entity's declarations, then export CSV or print.\"},{\"title\":\"Cost summary by company\",\"body\":\"Cost summary report aggregates invoice amount, total cost, and line-item amounts grouped by company and category — compare entities without separate databases.\"},{\"title\":\"Multi-entity consolidation\",\"body\":\"ERP → Multi-entity tab (when enabled) prepares inter-company eliminations and group reporting — entity switcher and consolidated P&L expand in later platform packs.\"}]},\"uae-vat-returns\":{\"intro\":\"Prepare VAT return data from posted sales and purchases with TRN-aware totals. Export-friendly views for tax advisors and in-house finance on UAE mainland entities.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-einvoice\",\"steps\":[{\"title\":\"Posted sales & purchases\",\"body\":\"VAT return data aggregates from posted ERP sales and purchase documents with TRN-aware totals.\"},{\"title\":\"Output vs input VAT\",\"body\":\"Standard-rated, zero-rated, and exempt lines separated — 5% UAE VAT on taxable supplies.\"},{\"title\":\"Advisor export\",\"body\":\"Export-friendly views for in-house finance or external tax advisors on UAE mainland entities.\"}]},\"peppol-einvoice\":{\"intro\":\"Issue UAE PINT-AE e-invoices from ERP Finance — Peppol-ready XML with TRN validation, document types 380/381, and a readiness checklist before ASP submission. Built into the finance module, not a separate bolt-on.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-einvoice\",\"steps\":[{\"title\":\"Open E-Invoicing tab\",\"body\":\"In client CP go to Shop → ERP Finance → E-Invoicing. The dashboard shows validated, submitted, and accepted counts plus a readiness checklist for go-live.\"},{\"title\":\"Configure seller profile\",\"body\":\"Enter legal name, TRN, TIN, UAE address, Peppol endpoint (0235 scheme), bank details, and payment terms under Seller profile. TRN drives TIN auto-fill for FTA compliance.\"},{\"title\":\"Buyer Peppol endpoints\",\"body\":\"For B2B buyers, capture Peppol endpoint IDs under Buyer Peppol. Use deemed-supply and export endpoint codes where transaction flags require them.\"},{\"title\":\"Document types 380 and 381\",\"body\":\"Tax invoices use type code 380; credit notes reference the original invoice with type 381. Commercial invoices follow the same PINT-AE specification ID urn:peppol:pint:billing-1@ae-1.\"},{\"title\":\"Generate from completed orders\",\"body\":\"From E-Invoicing → Generate or the Revenue tab, build an e-invoice from a completed order — line items, VAT breakdown, and buyer TRN pull from order and customer master data.\"},{\"title\":\"51-field validation before submit\",\"body\":\"The system validates all PINT-AE mandatory fields — seller and buyer TRN, addresses, line tax categories, totals, and payment means — before status moves from draft to validated.\"},{\"title\":\"Download PINT-AE XML / JSON\",\"body\":\"Validated documents export Peppol XML and JSON payloads suitable for your Accredited Service Provider. Print PDF tax invoices for customer delivery in parallel.\"},{\"title\":\"ASP submission & FTA timeline\",\"body\":\"Connect your ASP under ASP & FTA settings. Voluntary e-invoicing from 1 Jul 2026; mandatory phased from 1 Jan 2027 for entities with revenue ≥ AED 50M. FTA reporting runs through your ASP after validation.\"}]},\"tax-invoices-trn\":{\"intro\":\"Tax-inclusive pricing on storefront with seller TRN on invoices visible to clients. Create invoices from orders with legal footer blocks per UAE practice.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-einvoice\",\"steps\":[{\"title\":\"Seller TRN on documents\",\"body\":\"Configure TRN in company settings and e-invoice seller profile — appears on all customer tax invoices.\"},{\"title\":\"Tax-inclusive storefront\",\"body\":\"Display prices incl. VAT where required — invoice breakdown shows ex-VAT, VAT, and incl-VAT totals.\"},{\"title\":\"Create from order\",\"body\":\"Completed orders generate tax invoices with legal footer blocks per UAE practice — print or e-mail to client.\"}]},\"credit-notes\":{\"intro\":\"Issue credit notes linked to original tax invoices for returns and billing corrections. Maintains audit trail required for VAT reporting and client disputes.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-einvoice\",\"steps\":[{\"title\":\"Link to original invoice\",\"body\":\"Issue credit note referencing original tax invoice number — document type 381 in PINT-AE.\"},{\"title\":\"Returns & billing fixes\",\"body\":\"Partial or full credit for returns, pricing corrections, or goodwill — maintains VAT audit trail.\"},{\"title\":\"ERP & e-invoice sync\",\"body\":\"Credit notes post to GL and export Peppol XML alongside original invoice chain for FTA readiness.\"}]},\"fta-xml-export\":{\"intro\":\"Export e-invoice payloads in formats suitable for Peppol endpoints and FTA compliance workflows. Operators configure seller profile once per tenant in ERP.\",\"guide_area\":\"erp-finance\",\"image\":\"guide-einvoice\",\"steps\":[{\"title\":\"Validated payload export\",\"body\":\"Download PINT-AE XML or JSON from e-invoice document view after 51-field validation passes.\"},{\"title\":\"ASP handoff\",\"body\":\"Submit export to Accredited Service Provider — FTA tax data reporting runs through ASP after acceptance.\"},{\"title\":\"Archive & audit\",\"body\":\"Document library retains XML, PDF, and submission status for compliance audits.\"}]},\"document-templates\":{\"intro\":\"Branded invoice, delivery note, quote, and contract templates with merge fields from orders and customers. Tax advisory tenants use approval-ready document layouts.\",\"guide_area\":\"documents\",\"image\":\"guide-documents\",\"steps\":[{\"title\":\"Template manager\",\"body\":\"Shop → Document control → Templates — branded layouts for invoice, delivery note, quote, and contract.\"},{\"title\":\"Merge fields\",\"body\":\"Templates pull customer name, order lines, TRN, and bank details from live order and company data.\"},{\"title\":\"Approval-ready layouts\",\"body\":\"Tax advisory tenants use consistent document formats for client deliverables and FTA submissions.\"}]},\"print-documents\":{\"intro\":\"Print or PDF from CP for any operational document — orders, deliveries, statements. Consistent branding across storefront downloads and staff-printed copies.\",\"guide_area\":\"documents\",\"image\":\"guide-documents\",\"steps\":[{\"title\":\"Print from order card\",\"body\":\"Any operational document — order confirmation, delivery note, statement — prints or PDFs from CP.\"},{\"title\":\"Storefront downloads\",\"body\":\"Clients download invoices and statements from logged-in hub — same branding as staff-printed copies.\"},{\"title\":\"Batch print\",\"body\":\"Select multiple orders for pick list or delivery note batch print during peak fulfilment.\"}]},\"document-library\":{\"intro\":\"Store signed contracts, compliance files, and client deliverables per customer or order. Tax and consultancy verticals give clients secure download access from storefront hub.\",\"guide_area\":\"documents\",\"image\":\"guide-documents\",\"steps\":[{\"title\":\"Per-customer archive\",\"body\":\"Upload signed contracts, compliance files, and deliverables — link to customer or order record.\"},{\"title\":\"Secure client access\",\"body\":\"Tax and consultancy verticals expose selected files on storefront client hub with login gate.\"},{\"title\":\"Version history\",\"body\":\"Replace document while retaining audit of prior uploads for regulated industries.\"}]},\"legal-footers-trn\":{\"intro\":\"Configurable legal text, bank details, and TRN footer on all customer-facing documents. Reduces manual edits when onboarding new UAE entities.\",\"guide_area\":\"documents\",\"image\":\"guide-documents\",\"steps\":[{\"title\":\"Footer configuration\",\"body\":\"Company settings define legal text, bank IBAN, and TRN block applied to all customer-facing PDFs.\"},{\"title\":\"Multi-entity support\",\"body\":\"Different footers per branch or legal entity when group operates multiple UAE TRNs.\"},{\"title\":\"Reduce manual edits\",\"body\":\"New UAE entity onboarding updates footer once — all templates inherit automatically.\"}]},\"crm-pipeline\":{\"intro\":\"Native CRM kanban pipeline inside ERP — leads, opportunities, and won deals without a separate CRM subscription. Consultancies and B2B services run sales and billing on one stack.\",\"guide_area\":\"crm\",\"image\":\"guide-crm\",\"steps\":[{\"title\":\"Kanban pipeline\",\"body\":\"ERP → CRM → Pipeline — drag leads and opportunities across stages from enquiry to won.\"},{\"title\":\"No separate CRM bill\",\"body\":\"Native kanban inside ERP — consultancies and B2B services run sales and billing on one stack.\"},{\"title\":\"Won → order hint\",\"body\":\"Won opportunities link to order creation — smooth handoff from sales to commerce fulfilment.\"}]},\"leads-opportunities\":{\"intro\":\"Capture website enquiries as leads and convert to opportunities with value and stage tracking. Won opportunities hint order creation — smooth handoff to commerce.\",\"guide_area\":\"crm\",\"image\":\"guide-crm\",\"steps\":[{\"title\":\"Capture website leads\",\"body\":\"Storefront enquiry forms create CRM leads — assign owner and expected value in CP.\"},{\"title\":\"Convert to opportunity\",\"body\":\"Qualify lead to opportunity with stage, probability, and close date — track in pipeline kanban.\"},{\"title\":\"Activity logging\",\"body\":\"Calls and meetings logged against opportunity — nothing lost after showroom or advisory intake.\"}]},\"customer-hub\":{\"intro\":\"360° customer view: contacts, orders, balance, documents, and notes in one CP screen. Staff answer client calls without jumping between modules.\",\"guide_area\":\"crm\",\"image\":\"guide-crm\",\"steps\":[{\"title\":\"360° customer view\",\"body\":\"Shop → Customer management — contacts, orders, balance, documents, and notes on one screen.\"},{\"title\":\"Answer calls faster\",\"body\":\"Staff resolve client questions without jumping between orders, finance, and CRM modules.\"},{\"title\":\"CRM assignment\",\"body\":\"Link customer to CRM owner — new orders notify assigned manager automatically.\"}]},\"customer-approvals\":{\"intro\":\"Approve new B2B accounts, medical institutions, or advisory clients before they can order. Tax and regulated catalogue verticals gate access by design.\",\"guide_area\":\"crm\",\"image\":\"guide-crm\",\"steps\":[{\"title\":\"Pending queue\",\"body\":\"Users → Customer approvals lists wholesale and regulated sign-ups awaiting manager decision.\"},{\"title\":\"Approve with currency\",\"body\":\"On approve, assign fixed dealing currency and customer group — required for wholesale checkout.\"},{\"title\":\"Gate regulated catalogues\",\"body\":\"Medical and tax verticals block ordering until institutional approval completes.\"}]},\"customer-groups-profiles\":{\"intro\":\"Segment customers for pricing, catalog visibility, and marketing. Profiles drive margin rules and which brands or categories appear on login.\",\"guide_area\":\"crm\",\"image\":\"guide-crm\",\"steps\":[{\"title\":\"Segment buyers\",\"body\":\"Groups and profiles drive pricing, catalog visibility, and marketing — retail vs wholesale vs institutional.\"},{\"title\":\"Margin rules\",\"body\":\"Each profile links to price list and margin table — contract pricing applies at login automatically.\"},{\"title\":\"Brand visibility\",\"body\":\"Show or hide brands and categories per profile — premium lines visible only to approved B2B accounts.\"}]},\"activities-followups\":{\"intro\":\"Log calls, meetings, and tasks against leads and customers — nothing falls through after a showroom visit or advisory intake form.\",\"guide_area\":\"crm\",\"image\":\"guide-crm\",\"steps\":[{\"title\":\"Log activities\",\"body\":\"CRM → Activities — record calls, meetings, tasks against leads and customers with due dates.\"},{\"title\":\"Follow-up reminders\",\"body\":\"Due tasks surface on dashboard — sales team closes loop after site visit or advisory intake.\"},{\"title\":\"Order context\",\"body\":\"Activities visible on customer hub — staff see full relationship history on inbound call.\"}]},\"ai-parts-agent\":{\"intro\":\"Give workshop and fleet buyers a conversational parts expert on the storefront — search by part number, decode VIN, and get guided recommendations that reduce counter load.\",\"guide_area\":\"commerce\",\"image\":\"guide-ai\",\"steps\":[{\"title\":\"Enable on auto-parts storefront\",\"body\":\"The AI parts agent chat widget appears on industry auto-parts themes — buyers ask in natural language for part numbers, crosses, or VIN-based fitment.\"},{\"title\":\"VIN decode & catalogue context\",\"body\":\"AI-assisted VIN decode narrows vehicle make, model, and engine before browsing the Epart catalog — fewer wrong-fit orders and faster self-service.\"},{\"title\":\"Review sessions in CP\",\"body\":\"Staff open Shop → AI Parts Expert → Chats to review customer country, full transcript, and quoted articles before follow-up or order conversion.\"},{\"title\":\"Hand off to order desk\",\"body\":\"When the buyer adds recommended lines to cart and checks out, the session links to the standard order fulfilment pipeline — same LPO and ERP path as manual orders.\"}]},\"vin-decode-ai\":{\"intro\":\"AI-assisted VIN decode narrows vehicle context before catalogue browse — fewer wrong-fit orders and faster workshop self-service.\",\"guide_area\":\"automation\",\"image\":\"guide-ai\",\"steps\":[{\"title\":\"VIN entry on storefront\",\"body\":\"Buyer enters 17-character VIN in search or AI chat — decode narrows vehicle context instantly.\"},{\"title\":\"Catalogue filter\",\"body\":\"Decoded make/model/engine filters Epart browse and cross-reference results to compatible SKUs.\"},{\"title\":\"Fewer wrong-fit orders\",\"body\":\"Workshop self-service reduces counter calls and return rates from incorrect part selection.\"}]},\"demand-intelligence\":{\"intro\":\"Signals from search, crosses, and order history highlight what to stock and promote. Professional services pack includes demand views for advisory upsell.\",\"guide_area\":\"automation\",\"image\":\"guide-ai\",\"steps\":[{\"title\":\"Search & order signals\",\"body\":\"Dashboard aggregates popular searches, cross lookups, and repeat order patterns by SKU.\"},{\"title\":\"Stocking decisions\",\"body\":\"Highlight articles to reorder or promote — professional services pack adds advisory upsell views.\"},{\"title\":\"Campaign targeting\",\"body\":\"Feed merchandising and promo decisions — pair with Marketing campaigns hub for seasonal pushes.\"}]},\"auto-price-ai\":{\"intro\":\"Multi-source price intelligence for every tenant — crawl buy sources and sell marketplaces, compare margin, import winners to your catalogue, and list on Noon, Amazon, or eBay. Country packs, industry taxonomy, and scheduled crons keep prices fresh.\",\"guide_area\":\"automation\",\"image\":\"guide-ai\",\"steps\":[{\"title\":\"Enable on your tenant\",\"body\":\"Super CP enables Auto Price AI under Tenant features. First engine load seeds country sources, product lines, and sell marketplaces for your industry.\"},{\"title\":\"Discover → Quick crawl\",\"body\":\"Open Discover and run Quick crawl — cards show buy lowest, marketplace sell target, and margin. Review Marketplace opportunities or Market confirmed views.\"},{\"title\":\"Import to catalogue\",\"body\":\"Add to my catalogue sets cost = lowest buy and sell = marketplace target. Photos and specs copy across — you approve every import before publish.\"},{\"title\":\"List on marketplaces\",\"body\":\"Configure sell channels on Rules (Noon, Amazon.ae, eBay). Buy sources like Sharaf DG or spare247 are for sourcing only — never sell targets.\"},{\"title\":\"Full guide\",\"body\":\"Marketing overview at www.ecomae.com/platform/auto-price-ai — operator handbook in CP Auto Price AI → Guide tab.\"}]},\"automation-hooks\":{\"intro\":\"Event hooks for order placed, stock low, and lead captured — wire email, WhatsApp, or external systems. Foundation for operator-built automations per tenant.\",\"guide_area\":\"automation\",\"image\":\"guide-ai\",\"steps\":[{\"title\":\"Event triggers\",\"body\":\"Hooks fire on order placed, stock low, lead captured, and status changes — foundation for tenant automations.\"},{\"title\":\"E-mail & WhatsApp\",\"body\":\"Wire notifications to external channels — extend with operator-built scripts per tenant policy.\"},{\"title\":\"Integration ready\",\"body\":\"Standard events expose order and customer payload for middleware or accounting connectors.\"}]},\"marketing-campaigns\":{\"intro\":\"Plan and track campaigns linked to storefront landing pages and promo codes. Merchandising teams launch seasonal pushes without developer tickets.\",\"guide_area\":\"marketing\",\"image\":\"guide-marketing\",\"steps\":[{\"title\":\"Campaign planner\",\"body\":\"Shop → Marketing → Campaigns — name, date range, linked promo codes, and landing page URL with UTM tags.\"},{\"title\":\"Measure uplift\",\"body\":\"Track orders attributed to campaign codes — compare periods in order desk filters.\"},{\"title\":\"Seasonal launches\",\"body\":\"Merchandising teams push fashion and electronics collections without developer tickets.\"}]},\"growth-strategies\":{\"intro\":\"Built-in playbook of ten proven growth tactics — from basket recovery to B2B outreach — with CP guidance per strategy. Agencies show clients a structured marketing layer.\",\"guide_area\":\"marketing\",\"image\":\"guide-marketing\",\"steps\":[{\"title\":\"Ten-strategy playbook\",\"body\":\"Built-in growth tactics cover basket recovery, B2B outreach, cross-sell, and referral prompts.\"},{\"title\":\"CP guidance per strategy\",\"body\":\"Each strategy opens step-by-step checklist in CP — agencies show clients structured marketing layer.\"},{\"title\":\"Link to promos\",\"body\":\"Strategies connect to promo codes and featured collections for executable campaigns.\"}]},\"promo-merchandising\":{\"intro\":\"Hero banners, featured collections, and campaign-driven catalogue highlights on the storefront. UTM-ready URLs for measuring ad spend effectiveness.\",\"guide_area\":\"marketing\",\"image\":\"guide-marketing\",\"steps\":[{\"title\":\"Hero banners\",\"body\":\"Storefront theme editor places campaign banners on home and category pages — mobile-ready grids.\"},{\"title\":\"Featured SKUs\",\"body\":\"Pin promotional articles to collection grids — Virgin-style electronics and Namshi-style fashion layouts.\"},{\"title\":\"UTM tracking\",\"body\":\"Campaign URLs carry UTM parameters — measure ad spend effectiveness in analytics.\"}]},\"featured-collections\":{\"intro\":\"Curate lookbooks and collection grids — Namshi-style fashion and jewellery gallery layouts ship with industry themes. Mobile-ready grids for Instagram traffic.\",\"guide_area\":\"marketing\",\"image\":\"guide-marketing\",\"steps\":[{\"title\":\"Curate lookbooks\",\"body\":\"Shop → Marketing → Collections group SKUs for seasonal lookbooks and gallery grids.\"},{\"title\":\"Industry layouts\",\"body\":\"Fashion and jewellery themes render collection pages with large imagery and quick-add to cart.\"},{\"title\":\"Instagram traffic\",\"body\":\"Mobile-optimised grids convert social traffic — link collections from bio and paid ads.\"}]},\"users-roles\":{\"intro\":\"Role-based CP access for admin, warehouse, finance, and counter staff. Super CP operators stay on platform DB; client staff authenticate on their own domain only.\",\"guide_area\":\"admin\",\"image\":\"guide-admin\",\"steps\":[{\"title\":\"Role-based access\",\"body\":\"Users → Groups & roles assign admin, warehouse, finance, and counter permissions — sidebar hides unauthorised modules.\"},{\"title\":\"Client staff on own domain\",\"body\":\"Client employees authenticate on www.client.com/cp only — Super CP operators stay on platform hostname.\"},{\"title\":\"Audit user actions\",\"body\":\"Sensitive finance and approval actions log admin user — supports internal control reviews.\"}]},\"cp-module-packs\":{\"intro\":\"Enable or hide entire module packs — commerce, ERP, auto parts, logistics — per tenant. Sidebar groups stay clean; clients only see what their rental includes.\",\"guide_area\":\"admin\",\"image\":\"guide-admin\",\"steps\":[{\"title\":\"Industry pack toggles\",\"body\":\"Super CP or tenant admin enables commerce, ERP, auto parts, logistics packs per rental agreement.\"},{\"title\":\"Clean sidebar\",\"body\":\"Disabled modules hide from sidebar — clients only see included functionality.\"},{\"title\":\"Upgrade path\",\"body\":\"Enable ERP or e-invoice pack when tenant grows — no migration to new platform required.\"}]},\"ssl-dns-assist\":{\"intro\":\"Let's Encrypt certificates and DNS checklists handled on platform infrastructure. Tenants get HTTPS on www.client.com without managing certificates themselves.\",\"guide_area\":\"admin\",\"image\":\"guide-admin\",\"steps\":[{\"title\":\"Platform-managed SSL\",\"body\":\"Let's Encrypt certificates issue automatically when domain alias attaches — no client certificate management.\"},{\"title\":\"DNS checklist in onboarding\",\"body\":\"Step-by-step registrar guide included in tenant onboarding — operator verifies before go-live.\"},{\"title\":\"HTTPS everywhere\",\"body\":\"Storefront, /cp/, and /erp serve over HTTPS on client domain from day one.\"}]},\"storefront-themes\":{\"intro\":\"Five production retail and services layouts — automotive, electronics, fashion, jewellery, advisory — with industry-tuned CP chrome. Switch visual style without losing catalogue data.\",\"guide_area\":\"admin\",\"image\":\"guide-industry\",\"steps\":[{\"title\":\"Five production layouts\",\"body\":\"Automotive, electronics, fashion, jewellery, and advisory themes ship with industry-tuned CP chrome.\"},{\"title\":\"Switch visual style\",\"body\":\"Change theme in industry settings — catalogue and order data persist across theme switches.\"},{\"title\":\"Mobile-first retail\",\"body\":\"All themes responsive for UAE mobile commerce and WhatsApp-driven traffic.\"}]},\"operator-audit\":{\"intro\":\"Platform branding, contact JSON presets, and deploy audit for operators. Super CP settings never leak to client hostnames — enforced by hostname routing rules.\",\"guide_area\":\"admin\",\"image\":\"guide-admin\",\"steps\":[{\"title\":\"Platform settings\",\"body\":\"Super CP → Settings — platform branding, contact JSON presets, and default industry options.\"},{\"title\":\"Deploy audit log\",\"body\":\"Each template push records operator, target tenant, timestamp, and package version.\"},{\"title\":\"Hostname isolation\",\"body\":\"Operator tools never expose on client hostnames — enforced by multi-tenant routing rules.\"}]},\"industry-auto-parts\":{\"intro\":\"VIN-aware catalogue, supplier prices, crosses, procurement, and B2B balances — the full eParts-style stack pre-loaded for parts distributors in UAE & GCC.\",\"guide_area\":\"industry\",\"image\":\"guide-industry\",\"steps\":[{\"title\":\"Pre-loaded eParts stack\",\"body\":\"VIN search, supplier prices, crosses, procurement, B2B balances, and AI parts agent enabled out of box.\"},{\"title\":\"Warehouse & LPO setup\",\"body\":\"Template seeds UAE warehouse price lists and LPO e-mail placeholders — follow price and fulfilment guides.\"},{\"title\":\"Go live for distributors\",\"body\":\"Full path from supplier price upload to storefront search to order desk in one hosted domain.\"}]},\"industry-tax-advisory\":{\"intro\":\"Client portal, VAT workflows, document control, and advisory CRM on one hosted domain — Prime Invest-style layout for tax firms and corporate advisors.\",\"guide_area\":\"industry\",\"image\":\"guide-industry\",\"steps\":[{\"title\":\"Client portal hub\",\"body\":\"Prime Invest-style layout — clients log in for documents, VAT status, and advisory deliverables.\"},{\"title\":\"VAT & e-invoice pack\",\"body\":\"UAE VAT returns, PINT-AE e-invoicing, and document control pre-enabled for tax firms.\"},{\"title\":\"Advisory CRM\",\"body\":\"Pipeline and activities track engagements — bill from ERP without separate CRM subscription.\"}]},\"industry-fashion\":{\"intro\":\"Lookbook collections, variant catalogue, and campaign-ready Namshi-style storefront. Order fulfilment and returns modules aligned to apparel retail.\",\"guide_area\":\"industry\",\"image\":\"guide-industry\",\"steps\":[{\"title\":\"Namshi-style storefront\",\"body\":\"Lookbook collections, variant catalogue, and campaign-ready mobile grids.\"},{\"title\":\"Apparel fulfilment\",\"body\":\"Size/colour variants, returns module, and delivery notes aligned to fashion retail operations.\"},{\"title\":\"Seasonal CSV import\",\"body\":\"Bulk upload collections via CSV — map size run and colour columns in import wizard.\"}]},\"industry-electronics\":{\"intro\":\"Virgin-style mega navigation, spec-heavy homepage, and SKU pagination for IT and consumer electronics. RMA and warranty hooks included in pack.\",\"guide_area\":\"industry\",\"image\":\"guide-industry\",\"steps\":[{\"title\":\"Virgin-style navigation\",\"body\":\"Mega menu, spec-heavy homepage, and SKU pagination for IT and consumer electronics.\"},{\"title\":\"RMA & warranty\",\"body\":\"Serial number fields on order lines — RMA workflow with warranty claim tracking included in pack.\"},{\"title\":\"Spec filters\",\"body\":\"Category attributes drive datasheet filters on browse and search pages.\"}]},\"industry-medical\":{\"intro\":\"Regulated catalogue, institutional login, batch and expiry fields, and audit-friendly delivery documentation for clinic procurement teams.\",\"guide_area\":\"industry\",\"image\":\"guide-industry\",\"steps\":[{\"title\":\"Regulated catalogue\",\"body\":\"Institutional login and customer approval gate ordering for clinic procurement teams.\"},{\"title\":\"Batch & expiry\",\"body\":\"SKU fields capture batch number and expiry — audit-friendly delivery documentation.\"},{\"title\":\"Compliance documents\",\"body\":\"Document library stores certificates and MSDS — institutional buyers download from client hub.\"}]},\"industry-consultancy\":{\"intro\":\"Proposal-to-delivery: CRM, projects, billing, and client-facing hub for management consultancies and professional service firms.\",\"guide_area\":\"industry\",\"image\":\"guide-industry\",\"steps\":[{\"title\":\"Proposal to delivery\",\"body\":\"CRM pipeline, project tracking, time billing, and client-facing hub on one domain.\"},{\"title\":\"Professional services ERP\",\"body\":\"Invoice from opportunities, track receivables, and export P&L for management consultancies.\"},{\"title\":\"Client hub access\",\"body\":\"Secure document and statement downloads — reduce e-mail attachment friction.\"}]},\"industry-rental\":{\"intro\":\"Rental SKU with daily/monthly periods, deposits, contracts, and monthly billing hooks for fleet, equipment, and commercial leasing businesses.\",\"guide_area\":\"industry\",\"image\":\"guide-industry\",\"steps\":[{\"title\":\"Rental SKU periods\",\"body\":\"Daily, weekly, and monthly rate periods on rental SKUs — deposits and contract terms on order.\"},{\"title\":\"Contract generation\",\"body\":\"Document templates produce rental agreements with merge fields from customer and asset data.\"},{\"title\":\"Monthly billing hooks\",\"body\":\"Recurring invoice generation from active contracts — ties to ERP receivables.\"}]},\"industry-jewellery\":{\"intro\":\"Kiyasha-style gold and diamond aesthetic, gallery product cards, certificate metadata, and premium enquiry flows for fine jewellers.\",\"guide_area\":\"industry\",\"image\":\"guide-industry\",\"steps\":[{\"title\":\"Kiyasha-style aesthetic\",\"body\":\"Gold and diamond gallery product cards with certificate metadata fields.\"},{\"title\":\"Premium enquiry flows\",\"body\":\"High-value items use enquiry or appointment CTAs alongside cart for fine jewellers.\"},{\"title\":\"Luxury merchandising\",\"body\":\"Featured collections and hero imagery optimised for mobile Instagram traffic.\"}]},\"api-integrations\":{\"intro\":\"Read-only JSON REST at /epc-api/v1/ for enterprise middleware, BI dashboards, and partner systems — tenant-scoped API keys with OpenAPI spec and Super CP operator guide.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Review public API docs\",\"body\":\"Marketing page at www.ecomae.com/platform/api-documentation lists Phase 1 endpoints, auth, and curl examples with placeholders only.\"},{\"title\":\"Issue tenant API keys\",\"body\":\"Super CP → Portal → API documentation guide — run epc-api-keys-setup.php or insert hashed keys in epc_api_keys for each site_key.\"},{\"title\":\"Test read endpoints\",\"body\":\"curl tenant/info, orders, products/search, and erp/dashboard-summary with X-API-Key header — expect 401 without key.\"},{\"title\":\"Share OpenAPI with developers\",\"body\":\"Download /epc-api/v1/openapi.json for codegen and contract tests — Phase 2 will add webhooks and write APIs.\"}]},\"ext-reporting-centre\":{\"intro\":\"A country-driven statutory reporting centre that auto-builds filing-ready returns from your ERP data, localized to your registration country (UAE by default: FTA, MOHRE, goAML, MoEC). One catalogue covers tax, financial, audit, HR/WPS, AML and corporate filings — each in the official format with full sample data so nothing is ever blank.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Country drives the format\",\"body\":\"The registration country on the company profile selects the authority, official format, governing law and compliance rules — UAE tenants get the FTA/MOHRE/goAML layout automatically; the jurisdiction selector is preview only.\"},{\"title\":\"Pick report + period\",\"body\":\"Choose a report and reporting period (Monthly / Quarterly / Annual / Custom range) and click Run / Recalculate — the document rebuilds for that exact period and stamps the dates in the header.\"},{\"title\":\"Always complete\",\"body\":\"Figures come from posted GL/transactions; periods with no postings fall back to period-seeded sample data so the full return always renders end-to-end.\"},{\"title\":\"One-click filing pack\",\"body\":\"Download the Excel/CSV audit schedules or print the professional summary PDF — ready to file or hand to an advisor.\"}]},\"ext-ct-return\":{\"intro\":\"The complete UAE Corporate Tax return under Federal Decree-Law 47/2022 — taxpayer & period, elections/reliefs, accounting profit reconciled to taxable income through statutory adjustments, then 0% up to AED 375,000 and 9% above, with six supporting schedules and tax-group/intercompany handling.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Elections & reliefs\",\"body\":\"Section 2 captures Small Business Relief eligibility, Qualifying Free Zone Person status (0%/9%), realisation basis and group transfer relief — these reshape the whole computation.\"},{\"title\":\"Profit to taxable income\",\"body\":\"Section 3 adds back non-deductibles (fines 100%, entertainment 50%, donations, provisions, accounting depreciation) and deducts tax depreciation and exempt dividends, then applies the 30% EBITDA interest cap and 75% loss relief.\"},{\"title\":\"Bands & liability\",\"body\":\"Section 4 applies 0% on the first AED 375,000 and 9% above to give CT payable.\"},{\"title\":\"Schedules & compliance\",\"body\":\"Schedules 1–6 (adjustments, fixed-asset depreciation, exempt income, related-party/TP, tax losses, foreign tax credit) evidence every figure, and the compliance engine flags anything to review before filing.\"}]},\"ext-drill-txn\":{\"intro\":\"Every figure on a return is clickable in place: a box or computation line expands to its breakdown, a line expands to its invoices or entries, and a single invoice expands to its individual supply / GL lines — recursively, until you reach the individual transaction behind the number.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Click any figure\",\"body\":\"On the VAT or CT return, click an underlined figure to expand its source rows right inside the return — no separate report.\"},{\"title\":\"Keep drilling\",\"body\":\"Each sub-line is itself expandable: e.g. Accounting depreciation → asset class → the individual fixed-asset entry; or a VAT box → invoice → its supply/GL lines.\"},{\"title\":\"Always reconciles\",\"body\":\"Every breakdown sums exactly to its parent figure, so you can trace any total down to the transactions that make it up.\"}]},\"ext-compliance-engine\":{\"intro\":\"Each return is validated against the law with PASS / REVIEW / FAIL flags — VAT special schemes and CT conditions — so nothing is left to check before filing.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"VAT checks\",\"body\":\"24kt investment gold taxed 0%, B2B gold/diamonds under reverse charge, exports 0%, residential lease exempt, TRN present, and the return reconciles (Box 12 − Box 13 = Box 14).\"},{\"title\":\"CT checks\",\"body\":\"Non-deductibles added back, 30% EBITDA / AED 12m interest cap, exempt income excluded, 75% loss-relief cap, transfer-pricing disclosure for related parties, and Small Business Relief eligibility.\"},{\"title\":\"Clear before filing\",\"body\":\"Each finding cites its statutory basis and shows PASS / REVIEW / FAIL — work the list to green before you submit.\"}]},\"ext-period-control\":{\"intro\":\"Each report carries its own statutory period model — VAT monthly or quarterly, Corporate Tax by financial year (including non-calendar / transitional first periods via a custom range), WPS monthly, financials annual.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Right basis per report\",\"body\":\"The basis selector defaults to the report's statutory cycle and offers Monthly / Quarterly / Annual / Custom range as appropriate.\"},{\"title\":\"Custom year-ends\",\"body\":\"Use Custom range for a non-December financial year or a transitional first CT period — any From/To works.\"},{\"title\":\"Run / Recalculate\",\"body\":\"Changing the period rebuilds every figure and the drill-downs for that exact period, and stamps the dates on the document and PDF.\"}]},\"ext-audit-schedules\":{\"intro\":\"One-click Excel/CSV supporting schedules in the FTA layout — for both VAT and Corporate Tax — so you have the audit file behind every return.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"VAT audit files\",\"body\":\"Download invoice-wise, customer TRN-wise, supplier-wise and adjustments schedules in the FTA column layout.\"},{\"title\":\"CT audit files\",\"body\":\"Download adjustments, fixed-asset depreciation, exempt income, related-party / transfer pricing, tax losses and foreign tax credit schedules.\"},{\"title\":\"Excel-ready\",\"body\":\"Each file opens directly in Excel with a UTF-8 BOM, ready to attach to a filing or review per invoice / TRN / supplier.\"}]},\"ext-pro-pdf\":{\"intro\":\"A colour, MIS-style filing pack with cover page, section numbering, the summary schedules and a plain-language \\\"report explained\\\" commentary on both VAT and CT so a learner understands every figure.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Professional cover + sections\",\"body\":\"The PDF opens with a branded cover (company, TRN, period, authority, governing law) and clean numbered sections with running header/footer.\"},{\"title\":\"Schedules + commentary included\",\"body\":\"Summary supporting schedules and a narrative commentary explaining how each figure was derived print in the pack.\"},{\"title\":\"Summary, not 10k rows\",\"body\":\"Invoice-level detail is excluded so a tenant with thousands of invoices still gets a clean summary — the full detail stays in the Excel/CSV downloads.\"}]},\"ext-offsystem-import\":{\"intro\":\"Check or file other clients without touching the ERP: download a multi-sheet Excel template, fill it, upload, and the tool builds the full VAT/CT return and PDF entirely from the uploaded data.\",\"guide_area\":\"overview\",\"image\":\"guide-super-cp\",\"steps\":[{\"title\":\"Download the template\",\"body\":\"A multi-sheet Excel workbook: Company & TRN, the boxes/computation lines, invoice detail, a compliance checklist and instructions for every column.\"},{\"title\":\"Fill & upload\",\"body\":\"Enter the client's own TRN/address and summary figures, then upload the .xlsx or .csv — no ERP/GL data is touched.\"},{\"title\":\"Built return + PDF\",\"body\":\"The tool builds the full FTA VAT 201 / CT computation with the client's details, runs the compliance checks and produces the professional PDF.\"}]}}";

}
